@MainActor func transient_ProjectRoot_sheetGeometry (
       _ self_mSchematicSheetOrientation : SchematicSheetOrientation,
       _ self_mSchematicCustomWidth : CanariLength,  
       _ self_mSchematicCustomHeight : CanariLength
) -> SchematicSheetGeometry {
//--- START OF USER ZONE 2
  let A4MinSize = PAPER_A4_MIN_SIZE
  let A4MaxSize = PAPER_A4_MAX_SIZE
  let leftMargin = PAPER_LEFT_MARGIN
  let rightMargin = PAPER_RIGHT_MARGIN
  let topMargin = PAPER_TOP_MARGIN
  let bottomMargin = PAPER_BOTTOM_MARGIN
  switch self_mSchematicSheetOrientation {
  case .a4Horizontal :
    let width = A4MaxSize - leftMargin - rightMargin - CanariLength.pt (2.0)
    let height = A4MinSize - topMargin - bottomMargin - CanariLength.pt (2.0)
    return SchematicSheetGeometry (
      size: CanariSize (width: width, height: height),
      horizontalDivisions: Int ((10 * A4MaxSize) / A4MinSize),
      verticalDivisions: 10
    )
  case .a4Vertical :
    let width = A4MinSize - leftMargin - rightMargin - CanariLength.pt (2.0)
    let height = A4MaxSize - topMargin - bottomMargin - CanariLength.pt (2.0)
    return SchematicSheetGeometry (
      size: CanariSize (width: width, height: height),
      horizontalDivisions: 10,
      verticalDivisions: Int ((10 * A4MaxSize) / A4MinSize)
    )
  case .custom :
    let width = self_mSchematicCustomWidth
    let height = self_mSchematicCustomHeight
    let m = max (width, height)
    return SchematicSheetGeometry (
      size: CanariSize (width: width, height: height),
      horizontalDivisions: Int ((10 * width) / m),
      verticalDivisions: Int ((10 * height) / m)
    )
  }
//--- END OF USER ZONE 2
}

